#include <stdio.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

ll sq(ll x) { return x * x; }

ll dist2(Point a, Point b) {
    return sq(a.x - b.x) + sq(a.y - b.y);
}

// Check if point p is inside or on circle (center c, radius r)
int point_in_circle(Point p, Point c, ll r2) {
    return dist2(p, c) <= r2;
}

// Check if segment AB intersects circle (center c, radius r)
// Returns 1 if intersection or tangent, 0 otherwise
int segment_intersects_circle(Point a, Point b, Point c, ll r2) {
    ll dx = b.x - a.x;
    ll dy = b.y - a.y;
    ll fx = a.x - c.x;
    ll fy = a.y - c.y;

    ll a_coeff = dx*dx + dy*dy;
    ll b_coeff = 2*(fx*dx + fy*dy);
    ll c_coeff = fx*fx + fy*fy - r2;

    if (a_coeff == 0) {
        // degenerate segment (a == b), already handled by vertex check
        return 0;
    }

    // Check if the closest point on infinite line is within segment
    ll t = -b_coeff;
    if (t < 0 || t > 2*a_coeff) {
        // closest point is outside segment, check endpoints
        return 0;
    }

    // discriminant
    ll disc = b_coeff*b_coeff - 4*a_coeff*c_coeff;
    if (disc < 0) return 0;
    // If disc == 0 it's tangent, still intersection
    return 1;
}

