double dist_seg(double px, double py, double ax, double ay, double bx, double by) {
    double dx = bx-ax, dy = by-ay;
    double len2 = dx*dx+dy*dy;
    if(len2 == 0) return hypot(px-ax, py-ay);
    double t = ((px-ax)*dx+(py-ay)*dy)/len2;
    if(t<0) t=0; if(t>1) t=1;
    return hypot(px-(ax+t*dx), py-(ay+t*dy));
}

int point_in_tri(double px,double py,double ax,double ay,double bx,double by,double cx,double cy){
