#include <stdio.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

static double cross(Point a, Point b, Point c) {
    /* (b-a) x (c-a) */
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static double dot(Point a, Point b, Point c) {
    /* (b-a) . (c-a) */
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

static double dist2(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx * dx + dy * dy;
}

static int point_on_segment(Point p, Point a, Point b) {
    const double EPS = 1e-10;
    if (fabs(cross(a, b, p)) > EPS) return 0;
    if (dot(p, a, b) > EPS) return 0;
    return 1;
}

static int point_in_triangle(Point p, Point a, Point b, Point c) {
    const double EPS = 1e-10;
    double c1 = cross(a, b, p);
    double c2 = cross(b, c, p);
    double c3 = cross(c, a, p);

    int has_neg = (c1 < -EPS) || (c2 < -EPS) || (c3 < -EPS);
    int has_pos = (c1 > EPS) || (c2 > EPS) || (c3 > EPS);
    return !(has_neg && has_pos); /* inside or on boundary */
}

static double point_segment_dist2(Point p, Point a, Point b) {
    double vx = b.x - a.x, vy = b.y - a.y;
    double wx = p.x - a.x, wy = p.y - a.y;
    double vv = vx * vx + vy * vy;

    if (vv == 0.0) return dist2(p, a);

    double t = (vx * wx + vy * wy) / vv;
    if (t < 0.0) t = 0.0;
    if (t > 1.0) t = 1.0;

    Point proj = { a.x + t * vx, a.y + t * vy };
    return dist2(p, proj);
}

static int segments_intersect(Point a, Point b, Point c, Point d) {
    const double EPS = 1e-10;
    double c1 = cross(a, b, c);
    double c2 = cross(a, b, d);
    double c3 = cross(c, d, a);
    double c4 = cross(c, d, b);

    if (((c1 > EPS && c2 < -EPS) || (c1 < -EPS && c2 > EPS)) &&
        ((c3 > EPS && c4 < -EPS) || (c3 < -EPS && c4 > EPS))) {
        return 1;
    }

    if (fabs(c1) <= EPS && point_on_segment(c, a, b)) return 1;
    if (fabs(c2) <= EPS && point_on_segment(d, a, b)) return 1;
    if (fabs(c3) <= EPS && point_on_segment(a, c, d)) return 1;
    if (fabs(c4) <= EPS && point_on_segment(b, c, d)) return 1;

    return 0;
}

int main(void) {
    Point A, B, C, O;
    double r;

    if (scanf("%lf %lf %lf %lf %lf %lf %lf %lf %lf",
              &A.x, &A.y, &B.x, &B.y, &C.x, &C.y, &O.x, &O.y, &r) != 9) {
        return 0;
    }

    const double EPS = 1e-10;
    double r2 = r * r;

    /* 1) Check if circle center is inside triangle */
    int center_in_triangle = point_in_triangle(O, A, B, C);

    /* 2) Check if any triangle vertex is inside/on circle */
    int vertex_in_circle =
        (dist2(A, O) <= r2 + EPS) ||
        (dist2(B, O) <= r2 + EPS) ||
        (dist2(C, O) <= r2 + EPS);

    /* 3) Check if any triangle edge intersects circle */
    int edge_hits_circle =
        (point_segment_dist2(O, A, B) <= r2 + EPS) ||
        (point_segment_dist2(O, B, C) <= r2 + EPS) ||
        (point_segment_dist2(O, C, A) <= r2 + EPS);

    /*
      Positional relationship:
      - If boundaries/interiors have no common point => separate
      - If one contains the other completely without crossing boundary => contained
      - Otherwise => intersect
    */

    if (!center_in_triangle && !vertex_in_circle && !edge_hits_circle) {
        printf("Separate\n");
        return 0;
    }

    /* Circle completely inside triangle */
    if (center_in_triangle &&
        point_segment_dist2(O, A, B) >= r2 - EPS &&
        point_segment_dist2(O, B, C) >= r2 - EPS &&
        point_segment_dist2(O, C, A) >= r2 - EPS) {
        printf("Circle in triangle\n");
        return 0;
    }

    /* Triangle completely inside circle */
    if (dist2(A, O) <= r2 + EPS &&
        dist2(B, O) <= r2 + EPS &&
        dist2(C, O) <= r2 + EPS) {
        printf("Triangle in circle\n");
        return 0;
    }

    printf("Intersect\n");
    return 0;
}

