struct Point {
    ll x, y;
    Point() : x(0), y(0) {}
    Point(ll x, ll y) : x(x), y(y) {}
    Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
    ll cross(const Point& p) const { return x * p.y - y * p.x; }
    ll dot(const Point& p) const { return x * p.x + y * p.y; }
    ll dist2(const Point& p) const {
        ll dx = x - p.x, dy = y - p.y;
        return dx*dx + dy*dy;
    }
};

bool pointInTriangle(Point p, Point a, Point b, Point c) {
    Point ab = b - a, ac = c - a, ap = p - a;
    ll d00 = ab.dot(ab), d01 = ab.dot(ac), d02 = ab.dot(ap);
    ll d11 = ac.dot(ac), d12 = ac.dot(ap);
    ll denom = d00 * d11 - d01 * d01;
    if (denom == 0) return false;
    double u = (d11 * d02 - d01 * d12) / (double)denom;
    double v = (d00 * d12 - d01 * d02) / (double)denom;
    return (u >= 0 && v >= 0 && u + v <= 1);
}

// squared distance from point p to segment ab
ll pointSegmentDist2(Point p, Point a, Point b) {
    Point ab = b - a, ap = p - a, bp = p - b;
    ll ab2 = ab.dot(ab);
    if (ab2 == 0) return p.dist2(a);
    ll t = ap.dot(ab);
    if (t < 0) return p.dist2(a);
    if (t > ab2) return p.dist2(b);
    // projection lies on segment
    // distance = |cross(ab, ap)| / |ab|
    ll cross = abs(ab.cross(ap));
    // avoid sqrt: squared distance = cross^2 / ab2
    // but we compare with r^2, so we can compare cross^2 with r^2 * ab2
    return cross * cross;
}

