#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
};

static const double EPS = 1e-10;

double cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(const Point& a, const Point& b, const Point& c) {
    // (b-a) . (c-a)
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

double dist2(const Point& a, const Point& b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx * dx + dy * dy;
}

bool pointOnSegment(const Point& p, const Point& a, const Point& b) {
    if (fabs(cross(a, b, p)) > EPS) return false;
    return dot(p, a, b) <= EPS; // (a-p) . (b-p) <= 0
}

bool pointInTriangleInclusive(const Point& p, const Point& a, const Point& b, const Point& c) {
    double c1 = cross(a, b, p);
    double c2 = cross(b, c, p);
    double c3 = cross(c, a, p);

    bool nonneg = (c1 >= -EPS && c2 >= -EPS && c3 >= -EPS);
    bool nonpos = (c1 <= EPS && c2 <= EPS && c3 <= EPS);
    return nonneg || nonpos;
}

double pointSegmentDistance2(const Point& p, const Point& a, const Point& b) {
    double vx = b.x - a.x, vy = b.y - a.y;
    double wx = p.x - a.x, wy = p.y - a.y;

    double len2 = vx * vx + vy * vy;
    if (len2 < EPS) return dist2(p, a);

    double t = (vx * wx + vy * wy) / len2;
    if (t < 0.0) return dist2(p, a);
    if (t > 1.0) return dist2(p, b);

    Point proj{a.x + t * vx, a.y + t * vy};
    return dist2(p, proj);
}

bool segmentsIntersectInclusive(const Point& a, const Point& b, const Point& c, const Point& d) {
    double c1 = cross(a, b, c);
    double c2 = cross(a, b, d);
    double c3 = cross(c, d, a);
    double c4 = cross(c, d, b);

    if ((c1 > EPS && c2 < -EPS || c1 < -EPS && c2 > EPS) &&
        (c3 > EPS && c4 < -EPS || c3 < -EPS && c4 > EPS))
        return true;

    if (fabs(c1) <= EPS && pointOnSegment(c, a, b)) return true;
    if (fabs(c2) <= EPS && pointOnSegment(d, a, b)) return true;
    if (fabs(c3) <= EPS && pointOnSegment(a, c, d)) return true;
    if (fabs(c4) <= EPS && pointOnSegment(b, c, d)) return true;

    return false;
}

bool segmentCircleIntersectInclusive(const Point& a, const Point& b, const Point& o, double r) {
    return pointSegmentDistance2(o, a, b) <= r * r + EPS;
}

