    static boolean segmentIntersectsCircle(int x1, int y1, int x2, int y2, int cx, int cy, int r) {
        long dx = x2 - x1;
        long dy = y2 - y1;
        long fx = x1 - cx;
        long fy = y1 - cy;

        long a = dx * dx + dy * dy;
        long b = 2 * (fx * dx + fy * dy);
        long c = fx * fx + fy * fy - (long) r * r;

        if (a == 0) {
            // degenerate segment (point)
            return c <= 0;
        }

        long discriminant = b * b - 4 * a * c;
        if (discriminant < 0) return false;

        double t1 = (-b - Math.sqrt(discriminant)) / (2.0 * a);
        double t2 = (-b + Math.sqrt(discriminant)) / (2.0 * a);

        return (t1 >= 0 && t1 <= 1) || (t2 >= 0 && t2 <= 1) || (t1 < 0 && t2 > 1);
    }

    static boolean pointInTriangle(int px, int py, int[] x, int[] y) {
        long d1 = sign(px, py, x[0], y[0], x[1], y[1]);
        long d2 = sign(px, py, x[1], y[1], x[2], y[2]);
        long d3 = sign(px, py, x[2], y[2], x[0], y[0]);

        boolean hasNeg = (d1 < 0) || (d2 < 0) || (d3 < 0);
        boolean hasPos = (d1 > 0) || (d2 > 0) || (d3 > 0);

        return !(hasNeg && hasPos);
    }

    static long sign(int px, int py, int x1, int y1, int x2, int y2) {
        return (long)(x1 - px) * (y2 - py) - (long)(x2 - px) * (y1 - py);
    }

    static double distanceFromPointToLine(int px, int py, int x1, int y1, int x2, int y2) {
        long dx = x2 - x1;
        long dy = y2 - y1;
        long numerator = Math.abs((long)(x2 - x1) * (y1 - py) - (long)(x1 - px) * (y2 - y1));
        double denominator = Math.sqrt(dx * dx + dy * dy);
        return numerator / denominator;
    }
}

