import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static long dot(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
    }

    static long dist2(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    // Triangle includes boundary
    static boolean pointInTriangle(Point p, Point a, Point b, Point c) {
        long c1 = cross(a, b, p);
        long c2 = cross(b, c, p);
        long c3 = cross(c, a, p);

        boolean nonNeg = c1 >= 0 && c2 >= 0 && c3 >= 0;
        boolean nonPos = c1 <= 0 && c2 <= 0 && c3 <= 0;
        return nonNeg || nonPos;
    }

    // Minimum squared distance from point p to segment ab, compared with r^2
    static boolean segmentIntersectsCircle(Point a, Point b, Point p, long r2) {
        long abx = b.x - a.x;
        long aby = b.y - a.y;
        long apx = p.x - a.x;
        long apy = p.y - a.y;
        long bpx = p.x - b.x;
        long bpy = p.y - b.y;

        long ab2 = abx * abx + aby * aby;
        if (ab2 == 0) return dist2(a, p) <= r2;

        long dot1 = abx * apx + aby * apy;
        long dot2 = (-abx) * bpx + (-aby) * bpy;

        if (dot1 <= 0) return dist2(a, p) <= r2;
        if (dot2 <= 0) return dist2(b, p) <= r2;

        long cr = abx * apy - aby * apx;
        // distance^2 = cr^2 / ab2 <= r2  <=> cr^2 <= r2 * ab2
        return cr * cr <= r2 * ab2;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        Point a = new Point(fs.nextLong(), fs.nextLong());
        Point b = new Point(fs.nextLong(), fs.nextLong());
        Point c = new Point(fs.nextLong(), fs.nextLong());
        Point o = new Point(fs.nextLong(), fs.nextLong());
        long r = fs.nextLong();
        long r2 = r * r;

        boolean intersects = false;

        // 1) Any triangle vertex inside/on circle
        if (dist2(a, o) <= r2 || dist2(b, o) <= r2 || dist2(c, o) <= r2) {
            intersects = true;
        }

        // 2) Circle center inside/on triangle
        if (!intersects && pointInTriangle(o, a, b, c)) {
            intersects = true;
        }

        // 3) Any triangle edge intersects circle
        if (!intersects) {
            if (segmentIntersectsCircle(a, b, o, r2) ||
                segmentIntersectsCircle(b, c, o, r2) ||
                segmentIntersectsCircle(c, a, o, r2)) {
                intersects = true;
            }
        }

        System.out.println(intersects ? "YES" : "NO");
    }
}

