EPS = 1e-10

def dist2(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy

def cross(a, b, c):
    # (b-a) x (c-a)
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def point_in_triangle(p, a, b, c):
    # Boundary included
    c1 = cross(a, b, p)
    c2 = cross(b, c, p)
    c3 = cross(c, a, p)
    has_pos = (c1 > EPS) or (c2 > EPS) or (c3 > EPS)
    has_neg = (c1 < -EPS) or (c2 < -EPS) or (c3 < -EPS)
    return not (has_pos and has_neg)

def point_segment_distance2(p, a, b):
    ax, ay = a
    bx, by = b
    px, py = p
    vx, vy = bx - ax, by - ay
    wx, wy = px - ax, py - ay
    vv = vx * vx + vy * vy
    if vv == 0:
        return dist2(p, a)
    t = (wx * vx + wy * vy) / vv
    if t < 0:
        return dist2(p, a)
    if t > 1:
        return dist2(p, b)
    proj = (ax + t * vx, ay + t * vy)
    return dist2(p, proj)

